        const v = Math.max(0, u - k), p = P(XG, [BEAD[0][0] + (BEAD[1][0] - BEAD[0][0]) * v, BEAD[0][1] + (BEAD[1][1] - BEAD[0][1]) * v]);
        const Rr = rad * 9, c0 = Math.floor((p.x - Rr) / CW), c1 = Math.ceil((p.x + Rr) / CW), r0 = Math.floor((p.y - Rr) / CH), r1 = Math.ceil((p.y + Rr) / CH);
